'use strict';
const D=window.DOSUL_DATA,S=D.skills,E=DosulGraph.buildGraph(D),$=s=>document.querySelector(s),byId=id=>S.find(s=>s.id===id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const glyph={절명:'刃',연타:'拳',강타:'破',척살:'墨',저격:'弓',주술:'符',파멸:'雷',강인:'盾',기동:'影',헌신:'生',기만:'幻',제압:'鎖'};
let selected=S.find(s=>s.name==='삼단 찌르기').id,build=[],history=[],saved=[],storageOK=true;
try{const v=JSON.parse(localStorage.getItem('dosul-builds-v1')||'[]');if(Array.isArray(v))saved=v.filter(x=>x&&typeof x.name==='string'&&Array.isArray(x.skills)).map(x=>({...x,skills:cleanIds(x.skills)}));const v2=JSON.parse(localStorage.getItem('dosul-current-v1')||'[]');build=cleanIds(v2);}catch(e){storageOK=false;}
function cleanIds(ids){return [...new Set(Array.isArray(ids)?ids:[])].filter(id=>byId(id)&&!byId(id).ultimate).slice(0,5);}
function persist(){try{localStorage.setItem('dosul-builds-v1',JSON.stringify(saved));localStorage.setItem('dosul-current-v1',JSON.stringify(build));}catch(e){storageOK=false;toast('브라우저 저장이 제한되어 있습니다. 조합을 내보내 보관하세요.');}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function icon(s,cls='skill-icon'){return s.icon?`<img class="${cls}" src="${esc(s.icon)}" alt="${esc(s.name)} 아이콘" loading="lazy" width="40" height="40">`:`<span class="${cls} icon-fallback" aria-label="${esc(s.family)} 계열">${glyph[s.family]}</span>`;}
function source(s){return D.sources.find(x=>x.id===s.source);}
function chips(items,kind=''){return items.length?items.map(x=>`<span class="chip ${kind}">${esc(x)}</span>`).join(''):'<span class="muted">미기재</span>';}
function textOf(s){return [s.name,s.family,...s.buffs,...s.debuffs,...s.conditions.flatMap(x=>[x.effect,x.result]),s.notes].join(' ');}
function select(id,push=true){if(!byId(id))return;if(push&&id!==selected)history.push(selected);selected=id;renderList();renderGraph();renderDetail();$('#back').disabled=!history.length;}
function tab(name){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===name));document.querySelectorAll('nav [data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab===name));if(name==='catalog')renderTable();}
function renderList(){const q=$('#search').value.trim(),fam=$('#family').value,list=S.filter(s=>(!fam||s.family===fam)&&textOf(s).includes(q));$('#list-count').textContent=list.length+'개';$('#skill-list').innerHTML=list.length?list.map(s=>`<button class="skill-item ${selected===s.id?'selected':''}" data-select="${s.id}">${icon(s)}<span><b>${esc(s.name)}</b><small>${s.family} · ${s.ultimate?'궁극기':'일반·특별'}</small></span>${build.includes(s.id)?'<span class="in-build">✓</span>':''}</button>`).join(''):'<div class="empty">검색 결과가 없습니다.</div>';}
function types(){return ['explicit',...($('#general').checked?['general']:[]),...($('#resource').checked?['resource']:[]),...($('#conflict').checked?['conflict']:[])];}
function visibleEdges(){return E.filter(e=>types().includes(e.type));}
function renderGraph(){
 const edges=visibleEdges(),depth=+$('#depth').value,levels=new Map([[selected,0]]),inIds=[...new Set(edges.filter(e=>e.target===selected).map(e=>e.source))];
 for(const id of inIds.slice(0,8))if(id!==selected)levels.set(id,-1);
 let frontier=[selected];let hidden=inIds.length>8;
 for(let n=1;n<=depth;n++){const next=[...new Set(edges.filter(e=>frontier.includes(e.source)).map(e=>e.target))].filter(id=>!levels.has(id));if(next.length>8)hidden=true;for(const id of next.slice(0,8))levels.set(id,n);frontier=next.slice(0,8);}
 const occupied=[...new Set(levels.values())].sort((a,b)=>a-b),width=Math.max(480,occupied.length*205+30),height=Math.max(240,Math.max(...occupied.map(l=>[...levels.values()].filter(v=>v===l).length))*66+65),pos=new Map();
 occupied.forEach((l,col)=>{const ids=[...levels].filter(([id,level])=>level===l).map(([id])=>id);ids.forEach((id,i)=>pos.set(id,{x:20+col*205,y:45+(height-70)/(ids.length+1)*(i+1)-28}));});
 const graphEdges=edges.filter(e=>pos.has(e.source)&&pos.has(e.target)&&levels.get(e.target)>levels.get(e.source)),dedup=new Map();graphEdges.forEach(e=>{const key=e.source+'-'+e.target;if(!dedup.has(key)||e.type==='explicit')dedup.set(key,e);});
 let svg=`<svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${esc(byId(selected).name)}의 선행 효과와 후속 연계"><defs>${['explicit','general','conflict','resource'].map((t,i)=>`<marker id="arrow-${t}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="${['#3e8c73','#ae8550','#b05a4b','#6d75a2'][i]}"/></marker>`).join('')}</defs>`;
 occupied.forEach((l,col)=>svg+=`<text x="${20+col*205}" y="23" class="sub" font-size="10" fill="#77817a">${l===-1?'선행 도술':l===0?'선택한 도술':l+'단계 후속'}</text>`);
 for(const e of dedup.values()){const a=pos.get(e.source),b=pos.get(e.target),x1=a.x+160,x2=b.x,y1=a.y+25,y2=b.y+25;svg+=`<path class="edge ${e.type}" marker-end="url(#arrow-${e.type})" d="M${x1},${y1} C${x1+30},${y1} ${x2-30},${y2} ${x2-5},${y2}"><title>${esc(e.effect+' → '+e.result+(e.requires.length?' / 선행 필요: '+e.requires.join(', '):''))}</title></path><text class="edge-label" x="${(x1+x2)/2}" y="${(y1+y2)/2-5}" text-anchor="middle">${esc(e.effect)}</text>`;}
 for(const [id,p]of pos){const s=byId(id);svg+=`<g class="graph-node ${id===selected?'current':''}" tabindex="0" role="button" aria-label="${esc(s.name)} 선택" data-select="${id}" transform="translate(${p.x},${p.y})"><rect width="160" height="53" rx="8"/>${s.icon?`<image href="${esc(s.icon)}" x="8" y="9" width="32" height="32"/>`:``}<text x="${s.icon?48:12}" y="22">${esc(s.name)}${build.includes(id)?' ✓':''}</text><text x="${s.icon?48:12}" y="40" class="sub">${s.family} · ${s.ultimate?'궁극기':'도술'}</text></g>`;}
 svg+='</svg>';$('#graph').innerHTML=svg;
 const adjacent=edges.filter(e=>e.source===selected||e.target===selected),display=[...new Map(adjacent.map(e=>[e.source+e.target+e.effect+e.type,e])).values()];
 $('#connection-summary').textContent=`연계 근거 ${display.length}개${hidden?' · 그래프는 단계별 8개 표시':''}`;
 $('#connections').innerHTML=`${hidden?'<p class="muted">그래프는 단계별 최대 8개를 표시합니다. 선택한 도술의 전체 연결은 아래 목록에서 확인하세요.</p>':''}${display.length?display.map(e=>{const target=e.source===selected?e.target:e.source;return `<div class="connection"><span class="dot ${e.type}"></span><div class="text"><strong>${esc(byId(e.source).name)} → ${esc(byId(e.target).name)}</strong><br>${esc(e.effect)} → ${esc(e.result)}${e.requires.length?` <span class="warn">· ${esc(e.requires.join(', '))} 선행 필요</span>`:''}<br><small>${e.confidence}${e.knownBug?' · 🐞 알려진 버그 있음 (연결 유지)':''}${e.scope==='self'?' · 자신에게 부여한 효과':''}</small></div><button data-select="${target}">탐색</button></div>`;}).join(''):'<div class="empty">현재 표시 기준에서 명시된 연계가 없습니다.<br>상세 조건이나 조건 없는 강화 효과 옵션을 확인하세요.</div>'}`;
}
function renderDetail(){
 const s=byId(selected),src=source(s),ult=DosulGraph.activeUltimate(D,build);
 const missing=s.conditions.filter(c=>!E.some(e=>e.target===s.id&&e.effect===c.effect&&e.type==='explicit'));
 $('#detail').innerHTML=`<div class="skill-heading">${icon(s,'detail-icon')}<div><small>${s.family} · ${s.ultimate?'궁극기':'일반·특별'}</small><h2>${esc(s.name)}</h2></div></div><p class="skill-description">${esc(s.notes)}</p><dl class="effects"><dt>강화</dt><dd>${chips(s.buffs)}</dd><dt>약화</dt><dd>${chips(s.debuffs,'debuff')}</dd><dt>활용 조건</dt><dd>${s.conditions.length?s.conditions.map(c=>`<div class="condition"><span class="chip cond">${esc(c.effect)}</span> → ${esc(c.result)} <small>${c.scope==='self'?'자신':'대상'}</small></div>`).join(''):'<span class="muted">명시 조건 없음</span>'}</dd></dl>${missing.length?`<p class="warn compact-note">선행 미확인: ${missing.map(c=>esc(c.effect)).join(', ')}</p>`:''}<button class="primary" id="add" ${s.ultimate?'disabled':''}>${s.ultimate?(ult?.id===s.id?'궁극기 조건 충족':'동일 계열 3개 필요'):build.includes(s.id)?'편성에서 제거':'조합에 추가 ＋'}</button><div class="mechanics"><h3>${s.family} 신식</h3><p>${esc(D.families[s.family])}</p></div><p class="bug-status">${s.family==='주술'?'🐞 타 계열 쿨타임 감소 버그 있음 · 연계 유지':'버그 유무 미확인'}</p><div class="detail-footer"><a href="${esc(src.url)}" target="_blank" rel="noopener noreferrer">공식 설명 ↗</a><span title="피해 계수·쿨타임·지속시간·각성·돌파 현행 수치 미확인">수치 미확인</span></div>`;
 $('#add').addEventListener('click',()=>addToBuild(s.id));
}
function addToBuild(id){if(byId(id).ultimate)return;if(build.includes(id))build=build.filter(x=>x!==id);else if(build.length<5)build.push(id);else return toast('다섯 칸이 가득 찼습니다. 기존 도술을 제거한 뒤 추가하세요.');persist();renderBuild();select(selected,false);}
function renderBuild(){
 $('#slots').innerHTML=Array.from({length:5},(_,i)=>{const s=byId(build[i]);return `<div class="slot ${s?'filled':''}"><span class="slot-num">${String(i+1).padStart(2,'0')}</span>${s?`<button class="remove" data-remove="${s.id}" aria-label="${s.name} 제거">×</button>${icon(s)}<button class="slot-name" data-select="${s.id}"><b>${esc(s.name)}</b><small>${s.family}</small></button><div class="slot-controls"><button class="move" data-move="${i},-1" ${i===0?'disabled':''} aria-label="${s.name} 앞으로">←</button><button class="move" data-move="${i},1" ${i===build.length-1?'disabled':''} aria-label="${s.name} 뒤로">→</button></div>`:'<span class="muted">＋ 도술 선택</span>'}</div>`;}).join('');
 const ult=DosulGraph.activeUltimate(D,build),ids=[...build,...(ult?[ult.id]:[])],explicit=E.filter(e=>e.type==='explicit'&&ids.includes(e.source)&&ids.includes(e.target));
 $('#ultimate').innerHTML=ult?`<span class="good">✦ ${ult.family} 신식 조건 충족</span> · 궁극기 <button data-select="${ult.id}">${ult.name} ↗</button>`:'<span class="muted">동일 계열 3개 → 궁극기</span>';
 const intended=E.filter(e=>e.type==='resource'&&ids.includes(e.source)&&ids.includes(e.target));
 const links=explicit.map(e=>{const reversed=build.indexOf(e.source)>build.indexOf(e.target)&&!byId(e.target).ultimate;return `<span class="build-link">${esc(byId(e.source).name)} → ${esc(byId(e.target).name)} · ${esc(e.effect)}${e.requires.length?' · 추가 선행: '+esc(e.requires.join(', ')):''}${reversed?' <span class="warn">(편성 순서 역방향)</span>':''}</span>`;}).join('');
 const conflicts=E.filter(e=>e.type==='conflict'&&ids.includes(e.source)&&ids.includes(e.target));const recommendations=[...new Set(E.filter(e=>e.type==='explicit'&&ids.includes(e.source)&&!ids.includes(e.target)&&!byId(e.target).ultimate).map(e=>e.target))].slice(0,8);
 $('#build-analysis').innerHTML=`${links||'<p class="muted">조합 안에서 명시된 조건 연계가 아직 없습니다.</p>'}${intended.length?'<p>주술 구슬 활성 시 의도된 대기시간 감소 연계 '+intended.length+'개 · 주술 신식 개방 필요'+(intended.some(e=>e.knownBug)?' · 🐞 타 계열 적용 버그 있음 (연계 유지)':'')+'</p>':''}${conflicts.length?'<p class="warn">주의: 수면·변이는 후속 피해로 해제될 수 있습니다. 지속 피해가 남아 있는 동안에도 유지가 어려울 수 있습니다.</p>':''}${recommendations.length?'<p>이 조합에서 이어 갈 후보: '+recommendations.map(id=>`<button data-select="${id}">${esc(byId(id).name)} ↗</button>`).join(' ')+'</p>':''}<p class="muted">편성 순서는 사용 순서의 메모입니다. 효과의 지속시간·면역·거리·중첩·자원 조건을 검증한 자동 콤보가 아닙니다.</p>`;
 renderSaved();
}
function renderSaved(){const current=$('#saved').value;$('#saved').innerHTML='<option value="">선택하세요</option>'+saved.map((s,i)=>`<option value="${i}">${esc(s.name)} (${s.skills.length}개)</option>`).join('');$('#saved').value=current;}
function renderTable(){const q=$('#table-search').value.trim(),list=S.filter(s=>textOf(s).includes(q));$('#table-count').textContent=`${list.length} / 105개 · 궁극기 12개 포함 · 효과 미기재는 효과 없음의 확정이 아닙니다.`;$('#table-body').innerHTML=list.map(s=>`<tr><td><div class="table-skill">${icon(s)}<button data-table-select="${s.id}">${esc(s.name)} ↗</button></div><small>${s.family} / ${s.ultimate?'궁극기':'일반·특별'}</small></td><td>${chips(s.buffs)}</td><td>${chips(s.debuffs,'debuff')}</td><td>${s.conditions.map(c=>esc(c.effect)+' → '+esc(c.result)).join('<br>')||'—'}</td><td>${esc(s.notes)}<br><a href="${esc(source(s).url)}" target="_blank" rel="noopener noreferrer">공식 출처 ↗</a></td></tr>`).join('');}
function renderSources(){
 $('#source-content').innerHTML=`<div class="source-grid"><div class="source-card"><h3>수록 범위</h3><p>${esc(D.meta.coverage)}</p><p>12개 계열 · 일반·특별 93개 · 궁극기 12개. 공식 설명에서 확인 가능한 이름·기능·강화·약화·발동 조건·신식을 수록했습니다.</p><p>${esc(D.meta.unknown)}</p><p>레벨별 피해 계수, 쿨타임, 지속시간, 각성·돌파별 변화, 획득처·가격의 현행 전체 데이터는 확보하지 못했습니다.</p></div><div class="source-card"><h3>연결을 읽는 방법</h3><p><b>명시된 조건 연계</b>: A가 효과를 부여하고, B의 설명에 그 효과를 활용한다는 조건이 있을 때 A → B로 연결합니다.</p><p><b>조건 없는 강화 효과 (추정)</b>: 방어력 감소·피해 증가가 후속 공격에 도움이 될 수 있다는 일반 관계입니다. 실측 초당 피해량·우선순위는 아닙니다.</p><p><b>제어 해제 주의</b>: 수면·변이를 건 후 공격하면 제어가 풀릴 수 있음을 나타냅니다. 적의 강화 제거·면역·정화는 내 조합 시너지가 아니므로 긍정 연결로 만들지 않습니다.</p><p>조건부 부여 효과에는 추가 선행 조건을 남깁니다. 세 도술이 연결되어도 지속시간과 사용 순서까지 보장되지는 않습니다.</p></div><div class="source-card"><h3>자료 간 표기 차이</h3><p>${esc(D.meta.nameMismatch||'공식 소개와 전재본에 다른 효과 이름이 있습니다. 같은 효과라고 확인되지 않은 이름은 합치지 않습니다.')}</p><p>따라서 정밀/집중, 질풍/속공처럼 서로 다른 이름은 별개의 조건입니다. 동의어가 확정되기 전에는 연결이 빠질 수 있습니다. 연결 없음이 실전 시너지 없음의 뜻은 아닙니다.</p></div><div class="source-card"><h3>현재 상태와 예정 변경</h3><p>10월 16일 공식 오류 현황: 주술 영력으로 다른 계열의 재사용 대기시간이 줄어들지 않는 현상이 안내되어 있습니다. 사용자 설정에 따라 버그를 무시하고 의도된 효과로 연결합니다. ‘주술 신식 연계’를 켜면 해당 연결선에 버그 배지만 표시합니다. 공지에 없는 도술은 정상으로 단정하지 않고 유무 미확인으로 표시합니다.</p><p>10월 21일 도술 강화·돌파 초기화가 예고되었습니다. 각성은 유지된다는 안내가 있습니다. 이 도구는 자동 업데이트되지 않으므로 개편 후 재검증이 필요합니다.</p><p>10월 14일 패치의 광역/PvP 수치 변경을 전체 현행 계수로 역산하지 않았습니다.</p></div><div class="source-card"><h3>출처</h3>${D.sources.map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>${s.mirrorUrl?`<br><small><a href="${esc(s.mirrorUrl)}" target="_blank" rel="noopener noreferrer">비교용 전재본</a> · 원문과 다른 표기는 원문 우선</small>`:''}</p>`).join('')}</div><div class="source-card"><h3>내 데이터로 이어 쓰기</h3><p>전체 도감에서 CSV, 원본 JSON, 방향 그래프 JSON, Graphviz DOT를 내보낼 수 있습니다. 도술 연결선에는 방향·효과·결과·선행 조건·근거가 포함됩니다.</p><p>조합은 브라우저에 저장됩니다. 다른 기기로 옮길 때는 ‘조합 내보내기’와 ‘조합 가져오기’를 사용하세요. 궁극기는 다섯 칸에 직접 넣지 않고 동일 계열 3개 조건으로 계산합니다.</p></div></div>`;
}
function download(name,body,type='application/json'){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',e=>{const sel=e.target.closest('[data-select]'),t=e.target.closest('[data-tab]'),row=e.target.closest('[data-table-select]'),rm=e.target.closest('[data-remove]'),move=e.target.closest('[data-move]');if(sel)select(sel.dataset.select);if(t)tab(t.dataset.tab);if(row){tab('explore');select(row.dataset.tableSelect);$('.workspace').scrollIntoView({behavior:'smooth',block:'start'});}if(rm)addToBuild(rm.dataset.remove);if(move){const [i,delta]=move.dataset.move.split(',').map(Number);[build[i],build[i+delta]]=[build[i+delta],build[i]];persist();renderBuild();}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('g[data-select]')){e.preventDefault();select(e.target.dataset.select);}});
$('#family').innerHTML+=Object.keys(D.families).map(f=>`<option>${f}</option>`).join('');
$('#search').addEventListener('input',renderList);$('#family').addEventListener('change',renderList);$('#table-search').addEventListener('input',renderTable);['#depth','#general','#resource','#conflict'].forEach(id=>$(id).addEventListener('change',renderGraph));
$('#back').onclick=()=>{if(history.length)select(history.pop(),false);};$('#clear').onclick=()=>{build=[];persist();renderBuild();select(selected,false);};
$('#save').onclick=()=>{if(!build.length)return toast('먼저 도술을 하나 이상 추가하세요.');const name=prompt('조합 이름',byId(build[0]).name+'의 연계');if(!name?.trim())return;saved.push({name:name.trim().slice(0,80),skills:[...build],savedAt:new Date().toISOString()});persist();renderSaved();toast(storageOK?'조합을 저장했습니다.':'현재 세션에 저장했습니다. 내보내기로 보관하세요.');};
$('#load').onclick=()=>{const value=$('#saved').value;if(value==='')return toast('저장한 조합을 선택하세요.');build=cleanIds(saved[+value].skills);persist();renderBuild();select(build[0]||selected);toast('조합을 불러왔습니다.');};
$('#delete').onclick=()=>{const value=$('#saved').value;if(value==='')return;saved.splice(+value,1);persist();renderSaved();toast('저장한 조합을 삭제했습니다.');};
$('#export-build').onclick=()=>download('도술-나의-조합.json',JSON.stringify({schema:'dosul-build-v1',name:'나의 도술 조합',baseline:D.meta.baselineDate,skills:build,skillNames:build.map(id=>byId(id).name)},null,2));
$('#import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>100000)throw Error('파일이 너무 큽니다.');const v=JSON.parse(await file.text());if(v.schema!=='dosul-build-v1'||!Array.isArray(v.skills)||v.skills.length>5||v.skills.some(id=>!byId(id)||byId(id).ultimate)||new Set(v.skills).size!==v.skills.length)throw Error('유효한 도술 조합 파일이 아닙니다.');build=cleanIds(v.skills);persist();renderBuild();select(build[0]||selected);toast('조합을 가져왔습니다.');}catch(err){toast(err.message);}finally{e.target.value='';}};
$('#download-data').onclick=()=>download('도술-105개-데이터.json',JSON.stringify(D,null,2));
$('#download-graph').onclick=()=>download('도술-방향그래프.json',JSON.stringify({meta:D.meta,sources:D.sources,nodes:S,edges:E},null,2));
$('#download-dot').onclick=()=>{const lines=['digraph Dosul {','rankdir=LR;','node [shape=box,fontname="Malgun Gothic"];'];S.forEach(s=>lines.push(`${s.id} [label=${JSON.stringify(s.name+' / '+s.family)}];`));E.filter(e=>e.type==='explicit').forEach(e=>lines.push(`${e.source} -> ${e.target} [label=${JSON.stringify(e.effect+' → '+e.result+(e.requires.length?' (선행: '+e.requires.join(', ')+')':''))}];`));lines.push('}');download('도술-명시연계.dot',lines.join('\n'),'text/vnd.graphviz');};
$('#download-csv').onclick=()=>{const cell=s=>'"'+String(s??'').replaceAll('"','""')+'"',rows=[['ID','도술','계열','궁극기','강화','약화','조건 → 결과','기능','출처','수치·각성·돌파','버그 상태'],...S.map(s=>[s.id,s.name,s.family,s.ultimate,s.buffs.join(', '),s.debuffs.join(', '),s.conditions.map(c=>c.effect+' → '+c.result).join('; '),s.notes,source(s).url,'미확인',s.family==='주술'?'타 계열 쿨타임 감소 버그 있음 (연결 유지)':'유무 미확인'])];download('도술-105개-목록.csv','\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');};
$('#link-count').textContent=E.filter(e=>e.type==='explicit').length;renderList();renderBuild();renderGraph();renderDetail();renderSources();$('#back').disabled=true;
